                        echo "reverse preproc (detail): $comName, initializing values <br>";
                        foreach ($gateItems as $xid => $dSpec) {
                            $tmpOutParams[$cCtr] = array();
                            //                        $id = $dSpec["id"];
                            $id = $xid;
                            $subParams = array();

                            if (isset($tComSpec['static'])) {
