                                $tmpOutParams['static']["dtime"] = date("Y-m-d H:i:s");
                                $tmpOutParams['static']["keterangan"] = $this->configUiModul[$jenisTr]["steps"][$stepNumCurrent]["label"] . " nomor " . $no . " oleh " . my_name();


