                $this->cCodeData[$cCode]);


            $outResultLib = array(
                "sessionData" => $this->cCodeData[$cCode],
                //                "tmpNomerNota" => $tmpNomorNota,
                //                "transaksiId" => $insertID,
            );
            return $outResultLib;

