                cekHijau(":: UOPDATE transaksi dengan trID -> $prevTrID");
                $mongUpdateList['update']["main"][] = array(
                    "where" => array(
                        "id" => "$prevTrID",
                    ),
                    "value" => array(
                        "tail_number" => $stepNum,
                        "tail_code" => $this->configUiModul[$this->jenisTr]["steps"][$stepNum]["target"],
                        "status_4" => $this->cCodeData[$cCode]["main"]['status_4'],
                        "trash_4" => $this->cCodeData[$cCode]["main"]['trash_4'],
                    ),
                );
                cekHijau($this->CI->db->last_query());
            }
            //endregion

            //region cloner items to item_child
            if (sizeof($additionalData) > 0) {
                echo "<script>top.writeProgress('CLONING ITEMS TO ITEM CHILD...','head');</script>";
                cekHitam("ini data");
                $dataMdl = $additionalData["mdlName"];
                $this->CI->load->model("Mdls/" . $dataMdl);
                $da = new $dataMdl();
                $arrColl = $da->getFields();
                $selectedCol = array();
                foreach ($arrColl as $colSpec) {
                    $selectedCol[] = $colSpec['kolom'];
                }

                if (isset($this->cCodeData[$cCode]['items_child']) && sizeof($this->cCodeData[$cCode]['items_child'])) {
                    $gateData = isset($this->configUiModul[$this->jenisTr]['shopingCartDetailFields'][$stepNum]['gate']) ? $this->configUiModul[$this->jenisTr]['shopingCartDetailFields'][$stepNum]['gate'] : "detail";

                    $arrBlacklist = array(
                        "jml", "max_jml", "qty",
                    );
                    if (isset($this->cCodeData[$cCode]["items2_sum"])) {
                        unset($this->cCodeData[$cCode]["items2_sum"]);
                        unset($this->cCodeData[$cCode]["items2"]);
                        unset($this->cCodeData[$cCode]["tableIn_detail_values2_sum"]);
                    }
                    foreach ($this->cCodeData[$cCode]['items_child'] as $mainProdsID => $defData) {
                        if ($gateData == "detail") {
                            $itemsMain = isset($this->cCodeData[$cCode]["items"][$mainProdsID]) ? $this->cCodeData[$cCode]["items"][$mainProdsID] : array();
                        }
                        else {
                            $forceMainToItems = isset($this->configUiModul[$this->jenisTr]['shopingCartDetailFields'][$stepNum]['changeToItems'][$gateData]) ? $this->configUiModul[$this->jenisTr]['shopingCartDetailFields'][$stepNum]['changeToItems'][$gateData] : array();
                            if (sizeof($forceMainToItems) > 0) {
                                foreach ($forceMainToItems as $key1 => $key2) {
                                    $keyForce = strlen($key2) > 2 ? $key2 : $key1;
                                    $itemsMain[$key1] = isset($this->cCodeData[$cCode]["main"][$keyForce]) ? $this->cCodeData[$cCode]["main"][$keyForce] : "";
                                }
                                $itemsMain["jml"] = "1";
                                $itemsMain["qty"] = "1";
                                $itemsMain["max_jml"] = "1";
                            }
                            else {
                                matiHEre("detil aset gagal di tulis!");
                            }

                        }

                        $arrChilds = array_diff_key($itemsMain, array_flip($arrBlacklist));

                        $arrNew = array();
                        if (sizeof($itemsMain) > 0) {
                            foreach ($defData as $inID => $detil_child) {
                                $paramDetil = array_replace($arrChilds, $detil_child);
                                if (array_key_exists("id", $paramDetil)) {
                                    $paramDetil["parent_id"] = $paramDetil["id"];
                                    if (!isset($paramDetil["folders"]) || $paramDetil["folders"] == 0) {
                                        $paramDetil["folders"] = $paramDetil["pihakMainId"];
                                        $paramDetil["keterangan"] = $paramDetil["pihakMainName"];
                                    }
                                    unset($paramDetil["id"]);
                                }
                                $tmpData = array();
                                foreach ($selectedCol as $i => $coloum) {
                                    if (isset($paramDetil[$coloum])) {
                                        $tmpData[$coloum] = $paramDetil[$coloum];
                                    }
                                }

                                if (isset($paramDetil["subtotal"])) {
                                    $paramDetil["subtotal"] = $paramDetil["jml"] * $paramDetil["harga"];
                                }

                                $insertDataID = $da->addData($tmpData, $da->getTableName()) or die(lgShowError("Gagal menulis pengajuan data", __FILE__));

                                $paramDetil["id"] = $insertDataID;
                                echo "<script>top.writeProgress('PENGAJUAN DATA (TRID:$insertDataID)');</script>";
                                $this->cCodeData[$cCode]["items2_sum"][$insertDataID] = $paramDetil;
                                $this->cCodeData[$cCode]["items2"][$mainProdsID][$insertDataID] = $paramDetil;
                            }
                        }
                    }
                }
            }

            //endregion

            //region updater price
            if ($additionalDataPriceConf) {
                if (isset($this->cCodeData[$cCode]['itemPrice']) && sizeof($this->cCodeData[$cCode]['itemPrice']) > 0) {
                    $dComsName = isset($this->configUiModul[$this->jenisTr]["itemPrice"][$stepNum]['DComs']) ? $this->configUiModul[$this->jenisTr]["itemPrice"][$stepNum]['DComs'] : "";
                    $replacerFields = isset($this->configUiModul[$this->jenisTr]["itemPrice"][$stepNum]['fieldReplacer']) ? $this->configUiModul[$this->jenisTr]["itemPrice"][$stepNum]['fieldReplacer'] : array();

                    if (sizeof($replacerFields) > 0) {
                        foreach ($this->cCodeData[$cCode]['itemPrice'] as $Cid => $cData) {
                            foreach ($cData as $pID => $tmpField) {
                                foreach ($tmpField as $field => $value) {
                                    if (isset($replacerFields[$field])) {
                                        $source = $replacerFields[$field];
                                        $valReplacer = $this->cCodeData[$cCode]["items"][$pID][$source];
                                        //                                        cekLime("replace $field $value => $valReplacer");
                                        $this->cCodeData[$cCode]['itemPrice'][$Cid][$pID][$field] = $valReplacer;
                                    }
                                }

                                //arrPrint($tmpField);
                            }
                        }
                    }

                    $this->CI->load->model("DComs/" . $dComsName);
