                foreach ($this->cCodeData[$cCode]['tableIn_detail2'] as $iID => $dSpec) {
                    $dd = $tr->writeDetailEntries($insertID, $dSpec);
                    $insertIDs[] = $dd;

                    if ($epID != 999) {
                        $dd = $tr->writeDetailEntries($epID, $dSpec);
                        $insertIDs[] = $dd;

                    }

                }
            }


            if (isset($this->configUiModul[$this->jenisTr]['updateDueDate'][$stepNum])) {
                $dueDateConf = $this->configUiModul[$this->jenisTr]['updateDueDate'][$stepNum];
                $sourceDue = $dueDateConf['source'];
                $targetDue = $dueDateConf["target"];
                $datenow = date("Y-m-d");
                foreach ($sourceDue as $key => $val) {
                    $indexVal = isset($this->cCodeData[$cCode]['main_elements'][$key][$val]) ? $this->cCodeData[$cCode]['main_elements'][$key][$val] : 14;
                    $dueDate = dueDate($datenow, $indexVal);
                }
                $fieldDue = $tr->getFields()["dueDate"];
                $dataDue = array();
                foreach ($fieldDue as $kol) {
                    if (isset($this->cCodeData[$cCode]["tableIn_master"][$kol])) {
