                $dataDue['due_date'] = $dueDate;
                $validateDue = validateDueDate($this->cCodeData[$cCode]["main"]['customerID'], $this->cCodeData[$cCode]["main"]['dtime']);


                if ($validateDue['allow_create'] == "true") {
                    if (isset($this->cCodeData[$cCode]["main"]['piutang_dagang']) && $this->cCodeData[$cCode]["main"]['piutang_dagang'] > 0) {

                        $tr->writeDueDate($insertID, $dataDue);

