                        $paramSpec = $cn->getNewCount($cParams, $cValues[$i], $tokoID);

                        $cContent[$cRawParams][$cRawValues] = $paramSpec["value"];
                        switch ($paramSpec["id"]) {
                            case 0: //===counter type is new
